log(`Matching ${TASKS.length} reviewer pairs for topical weakness overlap`)

function buildPrompt(t) {
  const list1 = t.items1.map((it) => `[${it.idx}] ${it.text}`).join('\n')
  const list2 = t.items2.map((it) => `[${it.idx}] ${it.text}`).join('\n')
  return `You are comparing weakness/concern items raised by TWO DIFFERENT human reviewers of the SAME paper. Identify pairs of items that describe the SAME underlying weakness or concern (the same kind of complaint about the same aspect of the paper), even if worded differently.

Two items match ONLY if they are about the same underlying issue. They do NOT match merely because both mention the same general topic area.

=== REVIEWER 1 ITEMS (indexed) ===
${list1}

=== REVIEWER 2 ITEMS (indexed) ===
${list2}

For every pair of items (one from each list) that describe the SAME underlying weakness, return {idx1, idx2}. Do not include non-matching items. Return your result via the required structured output only.`
}

const CONCURRENCY = 5
const results = []
for (let i = 0; i < TASKS.length; i += CONCURRENCY) {
  const chunk = TASKS.slice(i, i + CONCURRENCY)
  const chunkResults = await parallel(chunk.map((t) => async () => {
    const out = await agent(buildPrompt(t), {
      label: `p${t.paper_idx}_${t.reviewer1}_${t.reviewer2}`,
      schema: SCHEMA,
      model: 'sonnet',
    })
    if (!out || !Array.isArray(out.matches)) return []
    const byIdx1 = Object.fromEntries(t.items1.map((it) => [it.idx, it]))
    const byIdx2 = Object.fromEntries(t.items2.map((it) => [it.idx, it]))
    return out.matches
      .filter((m) => byIdx1[m.idx1] && byIdx2[m.idx2])
      .map((m) => ({
        paper_idx: t.paper_idx,
        reviewer1: t.reviewer1,
        reviewer2: t.reviewer2,
        text1: byIdx1[m.idx1].text,
        text2: byIdx2[m.idx2].text,
        reliability1: byIdx1[m.idx1].reliability,
        reliability2: byIdx2[m.idx2].reliability,
        error_type1: byIdx1[m.idx1].error_type,
        error_type2: byIdx2[m.idx2].error_type,
      }))
  }))
  results.push(...chunkResults)
  log(`chunk ${i / CONCURRENCY + 1}/${Math.ceil(TASKS.length / CONCURRENCY)} done`)
}

const flat = results.filter(Boolean).flat()
log(`${flat.length} overlapping pairs found`)
return flat
